package solution

import (
	"math"
	"reflect"
	"testing"
)

func TestScaleReadingsLinearRangeWithNegatives(t *testing.T) {
	input := []int{-10, -5, 0, 5, 10}
	original := append([]int(nil), input...)
	got := ScaleReadings(input)
	want := []float64{0, 0.25, 0.5, 0.75, 1}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("ScaleReadings(%v) = %v, want %v", input, got, want)
	}
	if !reflect.DeepEqual(input, original) {
		t.Fatalf("input mutated: got %v, want %v", input, original)
	}
}

func TestScaleReadingsOrderDuplicatesAndConstantValues(t *testing.T) {
	got := ScaleReadings([]int{8, 2, 8, 5, 2})
	want := []float64{1, 0, 1, 0.5, 0}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("mixed result = %v, want %v", got, want)
	}

	constant := ScaleReadings([]int{-7, -7, -7})
	if !reflect.DeepEqual(constant, []float64{0, 0, 0}) {
		t.Fatalf("constant result = %v, want zeros", constant)
	}
}

func TestScaleReadingsEmptyIsNonNilAndResultDoesNotAlias(t *testing.T) {
	empty := ScaleReadings(nil)
	if empty == nil || len(empty) != 0 {
		t.Fatalf("empty result = %#v, want non-nil empty slice", empty)
	}

	input := []int{1, 3}
	got := ScaleReadings(input)
	got[0] = 99
	if !reflect.DeepEqual(input, []int{1, 3}) {
		t.Fatalf("result aliases input: %v", input)
	}
}

func TestScaleReadingsExtremeIntegers(t *testing.T) {
	got := ScaleReadings([]int{math.MinInt, 0, math.MaxInt})
	if len(got) != 3 {
		t.Fatalf("result length = %d, want 3", len(got))
	}
	if got[0] != 0 || got[2] != 1 {
		t.Fatalf("extreme endpoints = %v, want minimum 0 and maximum 1", got)
	}
	if math.IsNaN(got[1]) || math.IsInf(got[1], 0) || got[1] < 0 || got[1] > 1 {
		t.Fatalf("scaled zero is outside unit interval: %v", got[1])
	}
}

